<div class="page-heading admin-heading"><div><span class="eyebrow">Public enquiries</span><h1>Contact inbox</h1><p>Review website messages, respond through the authorised office mailbox, and record completion.</p></div><a class="button button-outline" href="<?= url('admin/enquiries') ?>">Refresh</a></div><nav class="filter-tabs"><a class="<?= $status===''?'active':'' ?>" href="<?= url('admin/enquiries') ?>">All</a><?php foreach(['new'=>'New','in_progress'=>'In progress','replied'=>'Replied','closed'=>'Closed','spam'=>'Spam'] as $key=>$label):?><a class="<?= $status===$key?'active':'' ?>" href="<?= url('admin/enquiries?status='.$key) ?>"><?= e($label) ?></a><?php endforeach?></nav><div class="enquiry-layout"><section class="card enquiry-list"><div class="card-heading"><div><span class="eyebrow">Inbox</span><h2><?= count($enquiries) ?> enquiries</h2></div></div><?php foreach($enquiries as $enquiry):?><a class="<?= $selected&&$selected['id']===$enquiry['id']?'active':'' ?>" href="<?= url('admin/enquiries?'.http_build_query(array_filter(['status'=>$status,'view'=>$enquiry['id']]))) ?>"><span class="status-dot status-<?= e($enquiry['status']) ?>"></span><div><b><?= e($enquiry['subject']) ?></b><small><?= e($enquiry['name']) ?> · <?= format_date($enquiry['created_at'],true) ?></small><p><?= e(mb_strimwidth($enquiry['message'],0,100,'…')) ?></p></div><span class="status-pill status-<?= e($enquiry['status']) ?>"><?= e(str_replace('_',' ',$enquiry['status'])) ?></span></a><?php endforeach?><?php if(!$enquiries):?><div class="empty-inline">No enquiries in this queue.</div><?php endif?></section><aside class="card enquiry-detail"><?php if($selected):?><div class="card-heading"><div><span class="eyebrow">Enquiry #<?= e($selected['id']) ?></span><h2><?= e($selected['subject']) ?></h2></div></div><div class="enquiry-contact"><div><span>From</span><b><?= e($selected['name']) ?></b></div><div><span>Email</span><a href="mailto:<?= e($selected['email']) ?>?subject=<?= rawurlencode('Re: '.$selected['subject']) ?>"><?= e($selected['email']) ?></a></div><?php if($selected['phone']):?><div><span>Phone</span><a href="tel:<?= e($selected['phone']) ?>"><?= e($selected['phone']) ?></a></div><?php endif?><div><span>Received</span><b><?= format_date($selected['created_at'],true) ?></b></div></div><div class="enquiry-message"><?= nl2br(e($selected['message'])) ?></div><form class="enquiry-reply-form" method="post" action="<?= url('admin/enquiries/'.$selected['id'].'/reply') ?>"><?= csrf_field() ?><label><span>Reply by email</span><textarea name="message" rows="6" maxlength="5000" required placeholder="Write the authorised institutional response…"></textarea></label><button class="button button-primary button-block">Send reply →</button><small>SMTP is used in production; local installations record the message in Email log.</small></form><form method="post" action="<?= url('admin/enquiries/'.$selected['id']) ?>"><?= csrf_field() ?><label><span>Processing status</span><select name="status"><?php foreach(['new'=>'New','in_progress'=>'In progress','replied'=>'Replied','closed'=>'Closed','spam'=>'Spam'] as $key=>$label):?><option value="<?= e($key) ?>"<?= selected($selected['status'],$key) ?>><?= e($label) ?></option><?php endforeach?></select></label><button class="button button-outline button-block">Update status</button></form><small class="privacy-note">Do not copy personal contact data into unauthorised systems. Status changes are audited.</small><?php else:?><div class="empty-state compact"><span>✉</span><h2>Select an enquiry</h2><p>Choose a message from the inbox to review it.</p></div><?php endif?></aside></div>
